"""Lexer for the jq frontend.

The lexer deliberately keeps string tokens intact; interpolation is parsed by
the parser because its contents are jq expressions rather than JSON text.
"""
from dataclasses import dataclass
import json
import re


@dataclass(frozen=True)
class Token:
    kind: str
    text: str


class LexError(ValueError):
    pass


KEYWORDS = {
    "as", "import", "include", "module", "def", "if", "then", "else",
    "elif", "and", "or", "end", "reduce", "foreach", "try", "catch",
    "label", "break",
}
OPERATORS = (
    "//=", "?//", "|=", "+=", "-=", "*=", "/=", "%=", "==", "!=",
    "<=", ">=", "..",
)
SINGLE = set(".?=,;:|+-*/%()[]{}$<>")
NUMBER = re.compile(r"(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?\Z")
WORD = re.compile(r"(?:[A-Za-z_][A-Za-z_0-9]*::)*[A-Za-z_][A-Za-z_0-9]*\Z")


def _string_end(source: str, start: int) -> int:
    index = start + 1
    while index < len(source):
        if source[index] == '"':
            backslashes = 0
            cursor = index - 1
            while cursor >= start and source[cursor] == "\\":
                backslashes += 1
                cursor -= 1
            if backslashes % 2 == 0:
                raw = source[start:index + 1]
                try:
                    # Validate ordinary JSON escapes now.  \( is jq
                    # interpolation and is intentionally validated later.
                    json.loads(raw.replace("\\(", "\\\\(")) if "\\(" in raw else json.loads(raw)
                except json.JSONDecodeError as error:
                    raise LexError("invalid string escape") from error
                return index + 1
        if source[index] == "\n" or source[index] == "\r":
            raise LexError("unterminated string")
        index += 1
    raise LexError("unterminated string")


def tokenize(source: str) -> list[Token]:
    result: list[Token] = []
    index = 0
    while index < len(source):
        char = source[index]
        if char.isspace():
            index += 1
            continue
        if char == "#":
            index += 1
            while index < len(source):
                if source[index] in "\r\n":
                    index += 1
                    break
                # An odd trailing backslash continues the comment line.
                if source[index] == "\\" and index + 1 < len(source) and source[index + 1] == "\n":
                    index += 2
                    continue
                index += 1
            continue
        if char == '"':
            end = _string_end(source, index)
            result.append(Token("STRING", source[index:end]))
            index = end
            continue
        if char == "@":
            match = re.match(r"@[A-Za-z0-9_]+", source[index:])
            if not match:
                raise LexError("invalid format token")
            text = match.group(0)
            result.append(Token("FORMAT", text[1:]))
            index += len(text)
            continue
        operator = next((value for value in OPERATORS if source.startswith(value, index)), None)
        if operator is not None:
            result.append(Token(operator, operator))
            index += len(operator)
            continue
        if char == "." and index + 1 < len(source) and re.match(r"[A-Za-z_]", source[index + 1]):
            match = re.match(r"\.[A-Za-z_][A-Za-z_0-9]*", source[index:])
            assert match is not None
            text = match.group(0)
            result.append(Token("FIELD", text[1:]))
            index += len(text)
            continue
        if char == "$":
            match = re.match(r"\$(?:[A-Za-z_][A-Za-z_0-9]*::)*[A-Za-z_][A-Za-z_0-9]*", source[index:])
            if not match:
                result.append(Token("$", "$"))
                index += 1
            else:
                text = match.group(0)
                result.append(Token("BINDING", text[1:]))
                index += len(text)
            continue
        if char in SINGLE:
            result.append(Token(char, char))
            index += 1
            continue
        end = index
        while end < len(source) and not source[end].isspace() and source[end] not in SINGLE and source[end] != '"' and source[end] != "#":
            if any(source.startswith(op, end) for op in OPERATORS):
                break
            end += 1
        text = source[index:end]
        if not text:
            raise LexError(f"invalid character: {source[index]!r}")
        if text in {"true", "false", "null"} or NUMBER.fullmatch(text):
            kind = "LITERAL"
        elif WORD.fullmatch(text):
            kind = text if text in KEYWORDS else "IDENT"
        else:
            raise LexError(f"invalid token: {text}")
        result.append(Token(kind, text))
        index = end
    result.append(Token("EOF", ""))
    return result
import json
from dataclasses import dataclass
from typing import Any
from jq_lexer import Token, tokenize

class ParseError(ValueError):
    pass
@dataclass(frozen=True)
class Identity: pass
@dataclass(frozen=True)
class Literal: value: Any
@dataclass(frozen=True)
class Field: name: str
@dataclass(frozen=True)
class Iterate: pass
@dataclass(frozen=True)
class Pipe: left: Any; right: Any
@dataclass(frozen=True)
class Comma: left: Any; right: Any
@dataclass(frozen=True)
class Array: expression: Any
@dataclass(frozen=True)
class Add: left: Any; right: Any
@dataclass(frozen=True)
class Interpolated: parts: tuple[Any, ...]

class Parser:
    def __init__(self, tokens: list[Token]): self.tokens, self.position = tokens, 0
    def current(self) -> Token: return self.tokens[self.position]
    def take(self, kind: str) -> Token:
        token = self.current()
        if token.kind != kind: raise ParseError(f"expected {kind}")
        self.position += 1
        return token
    def parse(self) -> Any:
        value = self.comma(); self.take("EOF"); return value
    def comma(self) -> Any:
        value = self.pipe()
        while self.current().kind == ",":
            self.position += 1; value = Comma(value, self.pipe())
        return value
    def pipe(self) -> Any:
        value = self.add()
        while self.current().kind == "|":
            self.position += 1; value = Pipe(value, self.add())
        return value

    def add(self) -> Any:
        value = self.primary()
        while self.current().kind == "+":
            self.position += 1
            value = Add(value, self.primary())
        return value
    def primary(self) -> Any:
        token = self.current()
        if token.kind == ".":
            self.position += 1
            value = Field(self.current().text) if self.current().kind in {"IDENT", "FIELD"} else Identity()
            if isinstance(value, Field): self.position += 1
        elif token.kind == "FIELD":
            self.position += 1; value = Field(token.text)
        elif token.kind == "LITERAL":
            self.position += 1; value = Literal(json.loads(token.text))
        elif token.kind == "STRING":
            self.position += 1; value = self.string_value(token.text)
        elif token.kind == "[":
            self.position += 1; value = Array(self.comma()); self.take("]")
        else: raise ParseError("unexpected token")
        if self.current().kind == "[":
            self.position += 1; self.take("]"); value = Iterate()
        return value

    def string_value(self, text: str) -> Any:
        body = text[1:-1]
        parts: list[Any] = []
        literal: list[str] = []
        index = 0
        while index < len(body):
            if body.startswith("\\(", index):
                if literal:
                    parts.append(Literal(json.loads('"' + ''.join(literal) + '"')))
                    literal = []
                depth, cursor = 1, index + 2
                quote = False
                while cursor < len(body) and depth:
                    if body[cursor] == '"' and (cursor == 0 or body[cursor - 1] != "\\"):
                        quote = not quote
                    if not quote:
                        if body[cursor] == "(": depth += 1
                        elif body[cursor] == ")": depth -= 1
                    cursor += 1
                if depth:
                    raise ParseError("unterminated interpolation")
                parts.append(parse(body[index + 2:cursor - 1]))
                index = cursor
            else:
                literal.append(body[index])
                index += 1
        if literal or not parts:
            parts.append(Literal(json.loads('"' + ''.join(literal) + '"')))
        return parts[0] if len(parts) == 1 else Interpolated(tuple(parts))

def parse(source: str) -> Any: return Parser(tokenize(source)).parse()

from collections.abc import Iterator
from typing import Any
from jq_parser import Add, Array, Comma, Field, Identity, Interpolated, Iterate, Literal, Pipe

class RuntimeErrorJq(Exception): pass

def evaluate(expression: Any, value: Any) -> Iterator[Any]:
    if isinstance(expression, Identity): yield value
    elif isinstance(expression, Literal): yield expression.value
    elif isinstance(expression, Interpolated):
        pieces = [list(evaluate(part, value)) for part in expression.parts]
        if any(not item for item in pieces):
            return
        import json
        for combination in __import__("itertools").product(*pieces):
            yield "".join(item if isinstance(item, str) else json.dumps(item, separators=(",", ":"), ensure_ascii=False) for item in combination)
    elif isinstance(expression, Field):
        if not isinstance(value, dict): raise RuntimeErrorJq("cannot index value")
        yield value.get(expression.name)
    elif isinstance(expression, Iterate):
        if isinstance(value, (list, dict)): yield from value if isinstance(value, list) else value.values()
        elif value is not None: raise RuntimeErrorJq("cannot iterate value")
    elif isinstance(expression, Pipe):
        for item in evaluate(expression.left, value): yield from evaluate(expression.right, item)
    elif isinstance(expression, Add):
        left_values = list(evaluate(expression.left, value))
        right_values = list(evaluate(expression.right, value))
        for left in left_values:
            for right in right_values:
                if isinstance(left, bool) or isinstance(right, bool):
                    raise RuntimeErrorJq("cannot add values")
                try:
                    yield left + right
                except (TypeError, ValueError) as error:
                    raise RuntimeErrorJq("cannot add values") from error
    elif isinstance(expression, Comma):
        yield from evaluate(expression.left, value); yield from evaluate(expression.right, value)
    elif isinstance(expression, Array): yield list(evaluate(expression.expression, value))
    else: raise RuntimeErrorJq("unknown expression")
import sys
from jq_evaluator import RuntimeErrorJq, evaluate
from jq_parser import ParseError, parse
from jq_values import encode_compact, parse_json

def main(argv: list[str]) -> int:
    if len(argv) != 2 or argv[0] != "-c" or not argv[1]:
        print("usage: jq -c PROGRAM", file=sys.stderr); return 3
    try: program = parse(argv[1])
    except (ParseError, ValueError) as error:
        print(str(error), file=sys.stderr); return 3
    try:
        for line in sys.stdin:
            if not line.strip():
                continue
            input_value = parse_json(line)
            for value in evaluate(program, input_value):
                sys.stdout.write(encode_compact(value) + "\n")
    except (RuntimeErrorJq, ValueError) as error:
        print(str(error), file=sys.stderr); return 5
    return 0
import sys
from pathlib import Path

import pytest

sys.path.insert(0, str(Path(__file__).parent.parent))

from jq_lexer import LexError, tokenize


def kinds(source: str) -> list[str]:
    return [token.kind for token in tokenize(source)]


def test_lexer_classifies_literals_fields_bindings_and_keywords():
    tokens = tokenize('42 .foo $value if .. @uri')
    assert [(token.kind, token.text) for token in tokens[:-1]] == [
        ("LITERAL", "42"),
        ("FIELD", "foo"),
        ("BINDING", "value"),
        ("if", "if"),
        ("..", ".."),
        ("FORMAT", "uri"),
    ]


def test_lexer_recognizes_longest_operators_in_source_order():
    assert kinds("!= == <= >= ?// //= |= += -= *= /= %= ..") == [
        "!=", "==", "<=", ">=", "?//", "//=", "|=", "+=", "-=", "*=", "/=", "%=", "..", "EOF",
    ]


def test_lexer_ignores_comments_but_not_comment_markers_in_strings():
    tokens = tokenize('"# text" # ignored\n 1')
    assert [token.text for token in tokens[:-1]] == ['"# text"', "1"]


def test_lexer_rejects_unterminated_strings_and_bad_escapes():
    with pytest.raises(LexError):
        tokenize('"unterminated')
    with pytest.raises(LexError):
        tokenize(r'"bad\q"')
import json, subprocess, sys
from pathlib import Path
ROOT = Path(__file__).parent.parent
def run(program, value):
    return subprocess.run([sys.executable, str(ROOT / "jq"), "-c", program], input=json.dumps(value)+"\n", capture_output=True, text=True)
def test_identity_runtime():
    result = run(".", None); assert result.returncode == 0; assert [json.loads(x) for x in result.stdout.splitlines()] == [None]
def test_array_iteration_preserves_generator_order():
    result = run("[.[]]", [1,2,3]); assert result.returncode == 0; assert [json.loads(x) for x in result.stdout.splitlines()] == [[1,2,3]]
def test_compile_error_exit_code(): assert run("[", {}).returncode == 3

def test_cli_adds_one_and_emits_compact_json():
    result = run(". + 1", 41)
    assert result.returncode == 0
    assert [json.loads(line) for line in result.stdout.splitlines()] == [42]

def test_cli_processes_newline_delimited_inputs_in_order():
    result = subprocess.run(
        [sys.executable, str(ROOT / "jq"), "-c", "."],
        input="1\n2\n3\n", capture_output=True, text=True,
    )
    assert result.returncode == 0
    assert [json.loads(line) for line in result.stdout.splitlines()] == [1, 2, 3]

def test_cli_emits_each_generator_result_as_a_line():
    result = run(".[]", ["a", "b", "c"])
    assert result.returncode == 0
    assert [json.loads(line) for line in result.stdout.splitlines()] == ["a", "b", "c"]

